/**
 * ir.ts — Phase 4: intermediate representation.
 *
 * Two IRs are produced from the checked AST:
 *
 * 1. Three-address code (TAC): a flat list of instructions, each with one
 *    operator and at most two operands, e.g.
 *        t1 = AND a b
 *        t2 = NOT c
 *        out = OR t1 t2
 *    It is generated by a post-order walk: operands are emitted before the
 *    operator that uses them, and every intermediate value gets a fresh
 *    temporary t1, t2, ... Each name is assigned exactly once, so the TAC is
 *    already in SSA form (combinational logic has no control flow, so no φ
 *    functions are ever needed).
 *
 * 2. A gate-level netlist: a directed acyclic graph whose nodes are inputs,
 *    constants, gates and outputs, and whose edges are nets (wires). COPY
 *    instructions become plain connections, not gates.
 */
import type { Expr } from './ast'
import type { SemanticResult } from './semantic'

export type GateOp = 'AND' | 'NAND' | 'OR' | 'NOR' | 'XOR' | 'XNOR' | 'NOT'
export type Op = GateOp | 'COPY'

export type Operand = { kind: 'var'; name: string } | { kind: 'const'; value: 0 | 1 }

export interface Instr {
  dest: string
  op: Op
  args: Operand[]
  /** Source line of the assignment this instruction came from. */
  line: number
}

export interface IRProgram {
  inputs: string[]
  outputs: string[]
  wires: string[]
  instrs: Instr[]
}

export const GATE_OPS: readonly GateOp[] = ['AND', 'NAND', 'OR', 'NOR', 'XOR', 'XNOR', 'NOT']
export const COMMUTATIVE: ReadonlySet<Op> = new Set(['AND', 'NAND', 'OR', 'NOR', 'XOR', 'XNOR'])

export const v = (name: string): Operand => ({ kind: 'var', name })
export const k = (value: 0 | 1): Operand => ({ kind: 'const', value })

export function operandToString(o: Operand): string {
  return o.kind === 'var' ? o.name : String(o.value)
}

/** `t1 = AND a b`, `out = OR t1 t2`, and plain copies as `x = a`. */
export function formatInstr(i: Instr): string {
  if (i.op === 'COPY') return `${i.dest} = ${operandToString(i.args[0])}`
  return `${i.dest} = ${i.op} ${i.args.map(operandToString).join(' ')}`
}

export function formatProgram(p: IRProgram): string {
  return p.instrs.map(formatInstr).join('\n')
}

export function gateCount(p: IRProgram): number {
  return p.instrs.filter((i) => i.op !== 'COPY').length
}

/** Generates three-address code from a semantically valid program. */
export function generateIR(sem: SemanticResult): IRProgram {
  const instrs: Instr[] = []
  const taken = new Set(sem.table.names())
  let tempCounter = 0
  const newTemp = (): string => {
    // Never clash with a user signal that happens to be called t1.
    let name: string
    do name = `t${++tempCounter}`
    while (taken.has(name))
    return name
  }

  /**
   * Post-order code generation. Returns the operand holding the expression's
   * value. If `dest` is given, the final instruction writes there directly,
   * so `out = a AND b` becomes one instruction rather than a temp plus a copy.
   */
  const gen = (e: Expr, line: number, dest?: string): Operand => {
    switch (e.kind) {
      case 'Ident':
      case 'Const': {
        const operand = e.kind === 'Ident' ? v(e.name) : k(e.value)
        if (dest) instrs.push({ dest, op: 'COPY', args: [operand], line })
        return operand
      }
      case 'Unary': {
        const a = gen(e.operand, line)
        const d = dest ?? newTemp()
        instrs.push({ dest: d, op: 'NOT', args: [a], line })
        return v(d)
      }
      case 'Binary': {
        const a = gen(e.left, line)
        const b = gen(e.right, line)
        const d = dest ?? newTemp()
        instrs.push({ dest: d, op: e.op, args: [a, b], line })
        return v(d)
      }
    }
  }

  for (const a of sem.assignments) gen(a.expr, a.span.line, a.target.name)

  return {
    inputs: sem.table.ofKind('input').map((s) => s.name),
    outputs: sem.table.ofKind('output').map((s) => s.name),
    wires: sem.table.ofKind('wire').map((s) => s.name),
    instrs,
  }
}

/** Applies one gate operator to bit values. */
export function applyOp(op: Op, a: 0 | 1, b: 0 | 1 = 0): 0 | 1 {
  switch (op) {
    case 'COPY': return a
    case 'NOT': return (a ^ 1) as 0 | 1
    case 'AND': return (a & b) as 0 | 1
    case 'OR': return (a | b) as 0 | 1
    case 'XOR': return (a ^ b) as 0 | 1
    case 'NAND': return ((a & b) ^ 1) as 0 | 1
    case 'NOR': return ((a | b) ^ 1) as 0 | 1
    case 'XNOR': return ((a ^ b) ^ 1) as 0 | 1
  }
}

/** Interprets TAC for one input vector; returns the value of every name. */
export function evaluateIR(p: IRProgram, inputs: Record<string, 0 | 1>): Record<string, 0 | 1> {
  const env: Record<string, 0 | 1> = { ...inputs }
  const read = (o: Operand): 0 | 1 => (o.kind === 'const' ? o.value : env[o.name] ?? 0)
  for (const i of p.instrs) env[i.dest] = applyOp(i.op, read(i.args[0]), i.args[1] ? read(i.args[1]) : 0)
  return env
}

/**
 * Compiles TAC into a fast evaluator for many input vectors (the truth table).
 * Names are resolved to array slots once, so each row is a tight loop over
 * small integers instead of string-keyed lookups: roughly 10× faster.
 * Slot 0 holds constant 0 and slot 1 constant 1.
 */
export function compileEvaluator(p: IRProgram): { run: (inputBits: ArrayLike<number>) => Uint8Array; slotOf: (name: string) => number } {
  const slots = new Map<string, number>()
  const slot = (name: string) => {
    let s = slots.get(name)
    if (s === undefined) { s = slots.size + 2; slots.set(name, s) }
    return s
  }
  p.inputs.forEach(slot)
  const operand = (o: Operand) => (o.kind === 'const' ? o.value : slot(o.name))
  const OPC: Record<Op, number> = { COPY: 0, NOT: 1, AND: 2, OR: 3, XOR: 4, NAND: 5, NOR: 6, XNOR: 7 }
  const code = new Int32Array(p.instrs.length * 4)
  p.instrs.forEach((i, n) => {
    code[n * 4] = OPC[i.op]
    code[n * 4 + 1] = operand(i.args[0])
    code[n * 4 + 2] = i.args[1] ? operand(i.args[1]) : 0
    code[n * 4 + 3] = slot(i.dest)
  })
  const inputSlots = p.inputs.map((n) => slots.get(n)!)
  const size = slots.size + 2
  const run = (bits: ArrayLike<number>) => {
    const m = new Uint8Array(size)
    m[1] = 1
    for (let k = 0; k < inputSlots.length; k++) m[inputSlots[k]] = bits[k] & 1
    for (let pc = 0; pc < code.length; pc += 4) {
      const a = m[code[pc + 1]], b = m[code[pc + 2]]
      let r: number
      switch (code[pc]) {
        case 0: r = a; break
        case 1: r = a ^ 1; break
        case 2: r = a & b; break
        case 3: r = a | b; break
        case 4: r = a ^ b; break
        case 5: r = (a & b) ^ 1; break
        case 6: r = (a | b) ^ 1; break
        default: r = (a ^ b) ^ 1
      }
      m[code[pc + 3]] = r
    }
    return m
  }
  // Unknown names (never assigned) read slot 0, i.e. constant 0.
  return { run, slotOf: (name) => slots.get(name) ?? 0 }
}

// ─────────────────────────── Netlist ───────────────────────────

export type NodeType = 'INPUT' | 'OUTPUT' | 'CONST0' | 'CONST1' | GateOp

export interface NetNode {
  id: string
  type: NodeType
  /** Ids of the nodes driving each input pin, in pin order. */
  inputs: string[]
  /** Display label (signal name for pins, operator for gates). */
  label: string
  /** Every TAC name whose value is carried by this node's output net. */
  names: string[]
  line?: number
}

export interface Netlist {
  nodes: NetNode[]
  gateCount: number
}

/**
 * Builds the gate-level DAG from TAC. Nodes are created in instruction order,
 * which is a topological order (inputs → gates → outputs).
 */
export function buildNetlist(p: IRProgram): Netlist {
  const nodes: NetNode[] = []
  const byId = new Map<string, NetNode>()
  const netOf = new Map<string, string>() // TAC name → node id
  const add = (n: NetNode) => {
    nodes.push(n)
    byId.set(n.id, n)
    return n
  }

  for (const name of p.inputs) {
    add({ id: `in:${name}`, type: 'INPUT', inputs: [], label: name, names: [name] })
    netOf.set(name, `in:${name}`)
  }
  const constNode = (value: 0 | 1): string => {
    const id = `const:${value}`
    if (!byId.has(id)) add({ id, type: value ? 'CONST1' : 'CONST0', inputs: [], label: String(value), names: [] })
    return id
  }
  const resolve = (o: Operand): string =>
    o.kind === 'const' ? constNode(o.value) : netOf.get(o.name) ?? constNode(0)

  for (const i of p.instrs) {
    if (i.op === 'COPY') {
      const src = resolve(i.args[0])
      netOf.set(i.dest, src)
      byId.get(src)?.names.push(i.dest)
      continue
    }
    const node = add({ id: `g:${i.dest}`, type: i.op, inputs: i.args.map(resolve), label: i.op, names: [i.dest], line: i.line })
    netOf.set(i.dest, node.id)
  }

  for (const name of p.outputs) {
    add({ id: `out:${name}`, type: 'OUTPUT', inputs: [netOf.get(name) ?? constNode(0)], label: name, names: [name] })
  }

  return { nodes, gateCount: nodes.filter((n) => GATE_OPS.includes(n.type as GateOp)).length }
}

/** Evaluates every node of a netlist for one input vector. */
export function evaluateNetlist(net: Netlist, inputs: Record<string, 0 | 1>): Record<string, 0 | 1> {
  const val: Record<string, 0 | 1> = {}
  for (const n of net.nodes) {
    const a = val[n.inputs[0]] ?? 0
    const b = val[n.inputs[1]] ?? 0
    switch (n.type) {
      case 'INPUT': val[n.id] = inputs[n.label] ?? 0; break
      case 'CONST0': val[n.id] = 0; break
      case 'CONST1': val[n.id] = 1; break
      case 'OUTPUT': val[n.id] = a; break
      default: val[n.id] = applyOp(n.type, a, b)
    }
  }
  return val
}
